return "tree=" + (tree != null) + " sheet=" + (sheet != null) + " theme=" + (theme != null);

const string panelPath = "Assets/UI/ToolkitDemo/Panel.asset";
if (UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Object>(panelPath) != null)
    throw new System.InvalidOperationException("Refusing to overwrite " + panelPath);
var scene = UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();
if (scene.path != "Assets/Scenes/Generated/E2E/ToolkitDemo.unity")
    throw new System.InvalidOperationException("Unexpected active scene " + scene.path);
if (UnityEngine.GameObject.Find("ToolkitDemo") != null)
    throw new System.InvalidOperationException("ToolkitDemo object already exists");
var tree = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.UIElements.VisualTreeAsset>("Assets/UI/ToolkitDemo/Screen.uxml");
var theme = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.UIElements.ThemeStyleSheet>("Assets/UI/ToolkitDemo/Theme.tss");
if (tree == null || theme == null) throw new System.InvalidOperationException("UXML/TSS import missing");
var panel = UnityEngine.ScriptableObject.CreateInstance<UnityEngine.UIElements.PanelSettings>();
if (panel.themeStyleSheet == null) panel.themeStyleSheet = theme;
panel.scaleMode = UnityEngine.UIElements.PanelScaleMode.ConstantPixelSize;
UnityEditor.AssetDatabase.CreateAsset(panel, panelPath);
var go = new UnityEngine.GameObject("ToolkitDemo");
var document = go.AddComponent<UnityEngine.UIElements.UIDocument>();
document.panelSettings = panel;
document.visualTreeAsset = tree;
UnityEditor.EditorUtility.SetDirty(panel);
UnityEditor.EditorUtility.SetDirty(document);
UnityEditor.AssetDatabase.SaveAssets();
UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(go.scene);
var saved = UnityEditor.SceneManagement.EditorSceneManager.SaveScene(go.scene);
return "go=" + go.name + " theme=" + UnityEditor.AssetDatabase.GetAssetPath(panel.themeStyleSheet) + " saved=" + saved;

